import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as s,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Cursor 教程","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/cursor/cursor.md","filePath":"zh/products/ai-coding/cursor/cursor.md","lastUpdated":1787044708000}'),r={name:"zh/products/ai-coding/cursor/cursor.md"};function n(o,t,d,l,h,c){return s(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="cursor-教程" tabindex="-1">Cursor 教程 <a class="header-anchor" href="#cursor-教程" aria-label="Permalink to &quot;Cursor 教程&quot;">​</a></h1><p>Cursor 是基于 VS Code 的 AI 编辑器：同一窗口里做 Tab 补全、<code>Cmd+K</code> 改选区、<code>Cmd+I</code> 让 Agent 读仓库、改文件、跑命令。</p><blockquote><p>配置键、快捷键全集、22 项功能矩阵见 <a href="./cursor-cheatsheet.html">速查表</a>。概念辨析见 <a href="./cursor-glossary.html">术语表</a>。场景配方见 <a href="./cursor-cookbook.html">Cookbook</a>。</p><p>官方文档按 changelog 连续改版。本页对齐 2026-08 的 <a href="https://cursor.com/docs" target="_blank" rel="noreferrer">cursor.com/docs</a>，不在标题里钉死编辑器小版本。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>会用 VS Code 打开文件夹、看 diff、跑终端</li><li>一台能登录 <a href="https://cursor.com" target="_blank" rel="noreferrer">cursor.com</a> 的机器（macOS / Windows / Linux）</li><li>一个<strong>已有版本控制</strong>的练习仓库——Agent 改文件会立刻落盘，git 是回滚手段</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完你能：</p><ol><li>在 5 分钟内完成「解释仓库 → 做一个小改 → 审 diff」</li><li>分清 Tab / Inline Edit / Agent / Plan / Debug</li><li>用 <code>AGENTS.md</code> 或一条 <code>.mdc</code> 规则让 Agent 记住包管理器和目录约定</li><li>用 <code>@</code> 精确喂上下文，并知道什么时候不要喂</li></ol><hr><h2 id="安装与登录" tabindex="-1">安装与登录 <a class="header-anchor" href="#安装与登录" aria-label="Permalink to &quot;安装与登录&quot;">​</a></h2><ol><li>打开 <a href="https://cursor.com/downloads" target="_blank" rel="noreferrer">Downloads</a>，安装对应系统的 Cursor。</li><li>打开应用并登录。</li><li><strong>File → Open Folder</strong>，选一个 git 仓库。不要先开空窗口乱生成。</li></ol><p>官方 Quickstart 原文路径：<a href="https://cursor.com/docs/get-started/quickstart" target="_blank" rel="noreferrer">Get started</a>。</p><p>设置入口：</p><table tabindex="0"><thead><tr><th>你想改</th><th>快捷键</th></tr></thead><tbody><tr><td>Cursor 设置（模型、Tab、索引）</td><td><code>Cmd+Shift+J</code> / <code>Ctrl+Shift+J</code></td></tr><tr><td>VS Code 通用设置</td><td><code>Cmd+,</code> / <code>Ctrl+,</code></td></tr><tr><td>命令面板</td><td><code>Cmd+Shift+P</code> / <code>Ctrl+Shift+P</code></td></tr></tbody></table><p>来源：<a href="https://cursor.com/docs/reference/keyboard-shortcuts" target="_blank" rel="noreferrer">Keyboard Shortcuts</a>。</p><hr><h2 id="五分钟第一例" tabindex="-1">五分钟第一例 <a class="header-anchor" href="#五分钟第一例" aria-label="Permalink to &quot;五分钟第一例&quot;">​</a></h2><p>目标：不写新功能，只验证「Agent 能读懂仓库、你能审它的 diff」。步骤来自官方 Quickstart。</p><h3 id="_1-打开-agent" tabindex="-1">1. 打开 Agent <a class="header-anchor" href="#_1-打开-agent" aria-label="Permalink to &quot;1. 打开 Agent&quot;">​</a></h3><p><code>Cmd+I</code> / <code>Ctrl+I</code> 打开侧栏 Agent。官方 Quickstart 和 Agent Overview 都把这个键写成入口。</p><h3 id="_2-先让它解释-不要让它写" tabindex="-1">2. 先让它解释，不要让它写 <a class="header-anchor" href="#_2-先让它解释-不要让它写" aria-label="Permalink to &quot;2. 先让它解释，不要让它写&quot;">​</a></h3><p>在仓库根打开 Agent，发送：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解释这个代码库：技术栈、目录怎么分、我该先读哪几个文件。</span></span>\n<span class="line"><span>不要修改任何文件。</span></span></code></pre></div><p>Cursor 会搜仓库、读相关文件、总结结构。这是官方说的「进入陌生仓库最快的方式」。</p><h3 id="_3-做一个低风险小改" tabindex="-1">3. 做一个低风险小改 <a class="header-anchor" href="#_3-做一个低风险小改" aria-label="Permalink to &quot;3. 做一个低风险小改&quot;">​</a></h3><p>官方建议第一任务要低风险：文案、小 UI、注释。指定结果，不要只说「改进一下」。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 README.md 的 Getting Started 节补一句：</span></span>\n<span class="line"><span>本仓库根目录使用 pnpm，不要运行 npm install。</span></span>\n<span class="line"><span>只改 README.md。改完列出 diff 摘要。</span></span></code></pre></div><p>如果你的练习仓库是 TypeScript，可以改成下面这条（仍然只动一个文件）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 src/utils/formatDate.ts 增加函数 formatISODate(date: Date): string，</span></span>\n<span class="line"><span>用 date.toISOString().slice(0, 10) 返回 YYYY-MM-DD。</span></span>\n<span class="line"><span>不要改其他文件。加上导出。改完说明如何手工验证。</span></span></code></pre></div><h3 id="_4-审-diff-跑项目已有检查" tabindex="-1">4. 审 diff，跑项目已有检查 <a class="header-anchor" href="#_4-审-diff-跑项目已有检查" aria-label="Permalink to &quot;4. 审 diff，跑项目已有检查&quot;">​</a></h3><p>Agent 改完后：</p><ol><li>看 diff 视图，确认只动了你允许的文件</li><li>让它跑仓库里<strong>已经存在</strong>的检查，不要发明新脚本名：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行这个项目已经在用的类型检查和 lint。不要新增配置文件。</span></span></code></pre></div><ol start="3"><li>自己再跑一次你平时用的命令（例如 <code>pnpm typecheck</code>），不要只信 Agent 口头说 pass</li></ol><h3 id="_5-大改切换-plan-mode" tabindex="-1">5. 大改切换 Plan Mode <a class="header-anchor" href="#_5-大改切换-plan-mode" aria-label="Permalink to &quot;5. 大改切换 Plan Mode&quot;">​</a></h3><p>跨多文件、需要调研、或要先对齐方案时：在 Agent 输入框按 <code>Shift+Tab</code> 转到 <strong>Plan Mode</strong>。官方流程是：</p><ol><li>研究仓库、找出相关文件</li><li>问澄清问题</li><li>写出可编辑的实现计划</li><li><strong>等你批准再写代码</strong></li></ol><p>计划默认存在用户主目录。点 <strong>Save to workspace</strong> 会放到工作区（官方 blog 写的是 <code>.cursor/plans/</code>），方便团队复用和中断后续跑。</p><hr><h2 id="四种模式" tabindex="-1">四种模式 <a class="header-anchor" href="#四种模式" aria-label="Permalink to &quot;四种模式&quot;">​</a></h2><p>同一套 Agent，约束不同。用 <code>Cmd+.</code> / <code>Ctrl+.</code> 打开模式菜单；Plan 也可用 <code>Shift+Tab</code> 轮换。</p><table tabindex="0"><thead><tr><th>模式</th><th>做什么</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td>搜代码、改文件、跑终端</td><td>目标清楚的实现和重构</td></tr><tr><td><strong>Ask</strong></td><td>只读问答（changelog：Ask 默认带搜索工具；<code>@Codebase</code> 工具已移除）</td><td>先理解，先别改</td></tr><tr><td><strong>Plan</strong></td><td>先出可编辑计划，批准后再实现</td><td>跨文件、需求糊、要对齐</td></tr><tr><td><strong>Debug</strong></td><td>多假设 → 打日志 → 你复现 → 用运行时数据修</td><td>能复现但找不到根因</td></tr></tbody></table><p>官方页面：<a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Agent Overview</a>、<a href="https://cursor.com/docs/agent/plan-mode" target="_blank" rel="noreferrer">Plan Mode</a>、<a href="https://cursor.com/docs/agent/debug-mode" target="_blank" rel="noreferrer">Debug Mode</a>。Ask 出现在 <a href="https://cursor.com/changelog" target="_blank" rel="noreferrer">changelog</a> 和论坛，2026-08 主导航没有单独的 Modes 长页。</p><h3 id="agent-使用时记住这三件事" tabindex="-1">Agent 使用时记住这三件事 <a class="header-anchor" href="#agent-使用时记住这三件事" aria-label="Permalink to &quot;Agent 使用时记住这三件事&quot;">​</a></h3><ol><li><strong>Checkpoints</strong>：大改前自动快照。走偏了在时间线 Restore，不要手工一件件撤。</li><li><strong>排队</strong>：Agent 工作时 <code>Enter</code> 把下一条指令排队；<code>Cmd+Enter</code> / <code>Ctrl+Enter</code> 立刻插入当前轮。</li><li><strong>新开会话</strong>：换任务、它开始循环犯错、一个逻辑单元结束——开新 Chat。需要旧上下文用 <code>@Chats</code>，不要整段粘贴。</li></ol><p>来源：<a href="https://cursor.com/docs/agent/overview" target="_blank" rel="noreferrer">Agent Overview</a>、<a href="https://cursor.com/docs/agent/prompting" target="_blank" rel="noreferrer">Prompting</a>、<a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">agent-best-practices</a>。</p><hr><h2 id="tab-与-inline-edit" tabindex="-1">Tab 与 Inline Edit <a class="header-anchor" href="#tab-与-inline-edit" aria-label="Permalink to &quot;Tab 与 Inline Edit&quot;">​</a></h2><h3 id="tab" tabindex="-1">Tab <a class="header-anchor" href="#tab" aria-label="Permalink to &quot;Tab&quot;">​</a></h3><p><a href="https://cursor.com/docs/tab/overview" target="_blank" rel="noreferrer">Tab</a> 是补全专用模型，不是 Agent。</p><ul><li>新字符：半透明 ghost text；改已有代码：行右侧 diff</li><li><code>Tab</code> 接受，<code>Esc</code> 拒绝；<code>Cmd+→</code> / <code>Ctrl+→</code> 按词接受</li><li>接受一次后再按 <code>Tab</code> 可跳到预测的下一处（同文件或跨文件）</li><li>TypeScript / Python 可自动补 import</li><li>状态栏可 Snooze、全局关、或按扩展名关（例如 markdown / JSON）</li></ul><p><strong>不要</strong>用 Agent 改「光标旁三行」。那是 Tab 的活。</p><h3 id="inline-edit" tabindex="-1">Inline Edit <a class="header-anchor" href="#inline-edit" aria-label="Permalink to &quot;Inline Edit&quot;">​</a></h3><p><a href="https://cursor.com/docs/inline-edit/overview" target="_blank" rel="noreferrer">Inline Edit</a>：<code>Cmd+K</code> / <code>Ctrl+K</code>。</p><ul><li>有选区：按指令改选区</li><li>无选区：在光标处生成，并带上周围代码（例如在函数名上触发会带整函数）</li><li><code>Opt+Enter</code> / <code>Alt+Enter</code>：Quick Question，先问再改；回复后说 <code>do it</code> 可落到代码</li><li>多文件或要长解释：把选区 <code>Cmd+L</code> / <code>Ctrl+L</code> 送到 Chat</li></ul><hr><h2 id="项目上下文" tabindex="-1">项目上下文 <a class="header-anchor" href="#项目上下文" aria-label="Permalink to &quot;项目上下文&quot;">​</a></h2><p>LLM 不会跨补全记住你的偏好。持久指令靠 Rules / <code>AGENTS.md</code>。完整机制见 <a href="./cursor-glossary.html#rules">术语表 · Rules</a>。</p><h3 id="最小-agents-md" tabindex="-1">最小 <code>AGENTS.md</code> <a class="header-anchor" href="#最小-agents-md" aria-label="Permalink to &quot;最小 `AGENTS.md`&quot;">​</a></h3><p>放在仓库根。官方把它定位成「没有 metadata 的简单替代」。子目录也可以再放一份。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Agent notes</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 包管理器是 pnpm。禁止 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`npm install`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`yarn`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 源码在 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`src/`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，测试在 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`src/**/*.test.ts`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 改完跑 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`pnpm typecheck`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 和 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`pnpm test`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> UI 组件规范看 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`src/components/Button.tsx`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，不要在规则里复制整份组件。</span></span></code></pre></div><h3 id="一条按文件生效的规则" tabindex="-1">一条按文件生效的规则 <a class="header-anchor" href="#一条按文件生效的规则" aria-label="Permalink to &quot;一条按文件生效的规则&quot;">​</a></h3><p><code>.cursor/rules</code> 里必须是 <strong><code>.mdc</code></strong>。纯 <code>.md</code> 会被规则系统忽略。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TypeScript 模块约定</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">globs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*.ts,**/*.tsx&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alwaysApply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 只用 ES modules（</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`import`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`export`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">），不要 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`require`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 优先具名导出。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 规范结构见 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`src/components/Button.tsx`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span></code></pre></div><p>四种触发与 frontmatter 对照在 <a href="./cursor-cheatsheet.html#rules-frontmatter">速查表 · Rules</a>。生成入口：Agent 里 <code>/create-rule</code>。</p><p>官方硬限制：<strong>单条 &lt; 500 行</strong>，大规则拆开；少写空话；用 linter 管风格，不要把整本 style guide 塞进规则。</p><hr><h2 id="怎么给上下文" tabindex="-1">怎么给上下文 <a class="header-anchor" href="#怎么给上下文" aria-label="Permalink to &quot;怎么给上下文&quot;">​</a></h2><p>来源：<a href="https://cursor.com/docs/agent/prompting" target="_blank" rel="noreferrer">Prompting</a>。</p><p>在输入框打 <code>@</code>：</p><table tabindex="0"><thead><tr><th>提及</th><th>作用</th></tr></thead><tbody><tr><td><code>@auth.ts</code> / <code>@src/components/</code></td><td>文件或文件夹。选中文件夹后再打 <code>/</code> 往下走</td></tr><tr><td><code>@Terminals</code></td><td>终端输出</td></tr><tr><td><code>@Chats</code></td><td>旧对话</td></tr><tr><td><code>@Commit (Diff of Working State)</code></td><td>未提交 diff</td></tr><tr><td><code>@Branch (Diff with Main)</code></td><td>相对主分支的分支 diff</td></tr><tr><td><code>@Browser</code></td><td>内置浏览器上下文</td></tr></tbody></table><p><strong>知道相关文件就 <code>@</code>；不确定就别堆。</strong> 官方：Agent 自己有 grep 和语义搜索。标一堆无关文件会稀释重点。</p><p>图片：拖进输入框，或 <code>Cmd+V</code> / <code>Ctrl+V</code> 粘贴截图。适合对稿 UI、贴报错。</p><p>模型：输入框上的 picker，或 <code>Cmd+/</code> / <code>Ctrl+/</code> 循环。可中途换模型（快模型探索，强模型实现）。清单见 <a href="https://cursor.com/docs/models-and-pricing" target="_blank" rel="noreferrer">Models &amp; Pricing</a>。</p><hr><h2 id="日常工作流-tutorial-弧线" tabindex="-1">日常工作流（Tutorial 弧线） <a class="header-anchor" href="#日常工作流-tutorial-弧线" aria-label="Permalink to &quot;日常工作流（Tutorial 弧线）&quot;">​</a></h2><p>把上面串成一条默认路径。更细的场景跳 <a href="./cursor-cookbook.html">Cookbook</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>打开仓库</span></span>\n<span class="line"><span>  → 新 Chat + Ask/Agent：「这仓库怎么工作」</span></span>\n<span class="line"><span>  → 写或更新 AGENTS.md / 一条规则（只写你刚纠正过两次的事）</span></span>\n<span class="line"><span>  → 小改：Tab 或 Cmd+K</span></span>\n<span class="line"><span>  → 中改：Agent，写清验收（测哪条命令、不要改哪些目录）</span></span>\n<span class="line"><span>  → 大改：Plan → 编辑计划 → 批准 → Agent 实现 → 跑已有检查</span></span>\n<span class="line"><span>  → 走偏：Restore Checkpoint，或回计划重跑</span></span>\n<span class="line"><span>  → 推 PR：Bugbot 或 /review-bugbot</span></span>\n<span class="line"><span>  → 人不在 / 要并行：Cloud Agents；人在终端 / CI：`agent`</span></span></code></pre></div><p>提示要具体。官方对比：</p><table tabindex="0"><thead><tr><th>弱</th><th>强</th></tr></thead><tbody><tr><td>给 auth.ts 加测试</td><td>按 <code>__tests__/</code> 现有模式给 <code>auth.ts</code> 的 logout 边界补测试，不要 mock</td></tr></tbody></table><hr><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>正确做法</th></tr></thead><tbody><tr><td>第一句话就「重构整个目录」</td><td>先解释，再做一个文件的小改，再 Plan</td></tr><tr><td>用 Agent 改光标旁三行</td><td>用 Tab 或 <code>Cmd+K</code></td></tr><tr><td>把 <code>.cursorrules</code> 单文件当唯一真相</td><td>新项目用 <code>.cursor/rules/*.mdc</code> 或 <code>AGENTS.md</code></td></tr><tr><td>规则里粘贴整份组件</td><td>写「见 <code>src/components/Button.tsx</code>」</td></tr><tr><td>把 Bugbot 当运行时调试</td><td>运行时用 Debug Mode；PR 用 Bugbot</td></tr><tr><td>长对话里换题接着聊</td><td>新 Chat + <code>@Chats</code></td></tr><tr><td>只信 Agent 说 tests passed</td><td>本地再跑你自己的命令</td></tr><tr><td>在没 git 的目录里开 Agent</td><td>先 <code>git init</code> / 打开已有仓库</td></tr></tbody></table><p>论坛补充（社区信号，不是官方保证）：有人报告 Plan 下 Agent 仍写代码（<a href="https://forum.cursor.com/t/plan-mode-is-not-respected-by-the-agent/151802" target="_blank" rel="noreferrer">Plan mode is not respected</a>）。若发生，立刻 Stop，Restore Checkpoint，把计划写得更死（「在我回复 APPROVE 之前不要改文件」）。</p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li><a href="./cursor-cookbook.html">Cookbook</a> — 修 bug、做功能、Rules、Bugbot、Cloud、CLI、MCP</li><li><a href="./design-mode.html">Design Mode</a> · <a href="./cloud-agents.html">Cloud Agents</a> · <a href="./cursor-cli.html">Cursor CLI</a></li><li><a href="./origin.html">Origin</a> · <a href="./security-agents.html">Security Agents</a> · <a href="./pr-routing.html">PR Routing</a> · <a href="./cursor-sdk.html">SDK</a></li><li><a href="./cursor-cheatsheet.html">速查表</a> — 矩阵、快捷键、配置模板</li><li><a href="./cursor-glossary.html">术语表</a> — 选型为什么那样切</li><li>回 <a href="./">学习地图</a> 看编辑器 vs CLI vs Cloud vs Origin vs SDK</li><li>官方：<a href="https://cursor.com/docs/get-started/quickstart" target="_blank" rel="noreferrer">Quickstart</a>、<a href="https://cursor.com/blog/agent-best-practices" target="_blank" rel="noreferrer">Agent best practices</a></li></ol>',87)])])}const m=a(r,[["render",n]]);export{b as __pageData,m as default};
